entries[90531] = { ["name"] = "Plans: Ghost Iron Shield Spike", ["text"] = "Use: Teaches you how to forge a Ghost Iron Shield Spike.\nRequires Pandaria Blacksmithing (15)\nRequires The Klaxxi\n- Honored\n\nGhost Iron Shield Spike\nBinds when equipped\nUse: Attaches a ghost iron spike to your shield that sometimes deals 42 damage when you block with it.\n\nAttaching a ghost iron spike to your shield causes it to become soulbound. Cannot be applied to items higher than level 320.\nSell Price:\nRequires Ghost Iron Bar (12)" }
entries[90532] = { ["name"] = "Plans: Living Steel Weapon Chain", ["text"] = "Use: Teaches you how to forge a Living Steel Weapon Chain.\nRequires Pandaria Blacksmithing (15)\nRequires The Klaxxi\n- Honored\n\nLiving Steel Weapon Chain\nBinds when equipped\nUse: Attaches a chain to your weapon, reducing the duration of Disarm effects by 50% and increasing your critical strike by 13. Does not stack with other similar effects. Attaching the weapon chain causes the weapon to become soulbound. Cannot be applied to items higher than level 320.\nRequires Living Steel" }
